import assert from 'node:assert';
import { describe, it } from 'node:test';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

describe('createInvoice', () => {
  it('creates a draft invoice with valid input', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(result.ok);
    assert.equal(result.value.customerId, 'C-001');
    assert.equal(result.value.issueDate, '2025-12-15');
    assert.equal(result.value.status, 'draft');
    assert.equal(result.value.lines.length, 2);
    assert.equal(result.value.lines[0].sku, 'DES-HOUR');
    assert.equal(result.value.lines[0].name, 'Design work (hour)');
    assert.equal(result.value.lines[0].qty, 5);
    assert.equal(result.value.lines[0].unitPrice, 8500);
    assert.equal(result.value.lines[0].vatRate, 21);
    assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
    assert.equal(result.value.lines[1].name, 'Development (hour)');
    assert.equal(result.value.lines[1].qty, 3);
  });

  it('returns CUSTOMER_NOT_FOUND for unknown customer', () => {
    const result = createInvoice({
      customerId: 'unknown-cust',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
  });

  it('returns DATE_INVALID for invalid date format', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '15-12-2025',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DATE_INVALID');
  });

  it('returns DATE_INVALID for non-existent date', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DATE_INVALID');
  });

  it('returns DATE_INVALID for invalid format without dashes', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '20251215',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DATE_INVALID');
  });

  it('returns NO_LINES for empty lines array', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [],
    });

    assert(!result.ok);
    assert.equal(result.error, 'NO_LINES');
  });

  it('returns NO_LINES for missing lines', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: undefined,
    });

    assert(!result.ok);
    assert.equal(result.error, 'NO_LINES');
  });

  it('returns QTY_INVALID for zero quantity', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'QTY_INVALID');
  });

  it('returns QTY_INVALID for negative quantity', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'QTY_INVALID');
  });

  it('returns QTY_INVALID for fractional quantity', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'QTY_INVALID');
  });

  it('returns UNKNOWN_SKU for invalid SKU', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'INVALID', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'UNKNOWN_SKU');
  });

  it('does not mutate input lines', () => {
    const inputLines = [{ sku: 'DES-HOUR', qty: 5 }];
    const linesCopy = JSON.parse(JSON.stringify(inputLines));

    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: inputLines,
    });

    assert.deepEqual(inputLines, linesCopy);
  });
});

describe('lineTotal', () => {
  it('calculates qty times unitPrice', () => {
    const line = { qty: 5, unitPrice: 8500 };
    assert.equal(lineTotal(line), 42500);
  });

  it('handles single unit', () => {
    const line = { qty: 1, unitPrice: 1000 };
    assert.equal(lineTotal(line), 1000);
  });

  it('handles large quantities', () => {
    const line = { qty: 100, unitPrice: 5000 };
    assert.equal(lineTotal(line), 500000);
  });
});

describe('invoiceTotals', () => {
  it('calculates subtotal and total for a single line', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.total, 42500);
  });

  it('calculates subtotal and total for multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 5, unitPrice: 8500 },
        { qty: 3, unitPrice: 9500 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500 + 28500);
    assert.equal(totals.total, 42500 + 28500);
  });

  it('handles empty invoice', () => {
    const invoice = { lines: [] };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 0);
    assert.equal(totals.total, 0);
  });

  it('works with invoice from createInvoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const expectedSubtotal = 5 * 8500 + 3 * 9500;
    assert.equal(totals.subtotal, expectedSubtotal);
    assert.equal(totals.total, expectedSubtotal);
  });
});
